13	// BatchBuilder implements Batcher
14	type BatchBuilder struct {
15		pool          RequestPool
16		submittedChan chan struct{}
17		maxMsgCount   int
18		maxSizeBytes  uint64
19		batchTimeout  time.Duration
20		closeChan     chan struct{}
21		closeLock     sync.Mutex // Reset and Close may be called by different threads
22	}
23	
24	// NewBatchBuilder creates a new BatchBuilder
25	func NewBatchBuilder(pool RequestPool, submittedChan chan struct{}, maxMsgCount uint64, maxSizeBytes uint64, batchTimeout time.Duration) *BatchBuilder {
26		b := &BatchBuilder{
27			pool:          pool,
28			submittedChan: submittedChan,
29			maxMsgCount:   int(maxMsgCount),
30			maxSizeBytes:  maxSizeBytes,
31			batchTimeout:  batchTimeout,
32			closeChan:     make(chan struct{}),
33		}
34		return b
35	}
36	
37	// NextBatch returns the next batch of requests to be proposed.
38	// The method returns as soon as the batch is full, in terms of request count or total size, or after a timeout.
39	// The method may block.
40	func (b *BatchBuilder) NextBatch() [][]byte {
41		currBatch, full := b.pool.NextRequests(b.maxMsgCount, b.maxSizeBytes, true)
42		if full {
43			return currBatch
44		}
45	
46		timeout := time.After(b.batchTimeout) // TODO use task-scheduler based on logical time
47	
48		for {
49			select {
50			case <-b.closeChan:
51				return nil
52			case <-timeout:
53				currBatch, _ = b.pool.NextRequests(b.maxMsgCount, b.maxSizeBytes, false)
54				return currBatch
55			case <-b.submittedChan:
56				// there is a possibility to extend the current batch
57				currBatch, full = b.pool.NextRequests(b.maxMsgCount, b.maxSizeBytes, true)
58				if full {
59					return currBatch
60				}
61			}
62		}
63	}
64	
65	// Close closes the close channel to stop NextBatch
66	func (b *BatchBuilder) Close() {
67		b.closeLock.Lock()
68		defer b.closeLock.Unlock()
69		select {
70		case <-b.closeChan:
71			return
72		default:
73		}
74		close(b.closeChan)
75	}
76	
77	// Closed returns true if the batcher is closed
78	func (b *BatchBuilder) Closed() bool {
79		select {
80		case <-b.closeChan:
81			return true
82		default:
83			return false
84		}
85	}
86	
87	// Reset reopens the close channel to allow calling NextBatch
88	func (b *BatchBuilder) Reset() {
89		b.closeLock.Lock()
90		defer b.closeLock.Unlock()
91		b.closeChan = make(chan struct{})
92	}
