6	package bft
7	
8	import (
9		"container/heap"
10		"sync"
11		"sync/atomic"
12		"time"
13	)
14	
15	type Stopper interface {
16		Stop()
17	}
18	
19	type Task struct {
20		Deadline time.Time
21		F        func()
22		stopped  uint32
23	}
24	
25	func (t *Task) Stop() {
26		atomic.StoreUint32(&t.stopped, 1)
27	}
28	
29	func (t *Task) isStopped() bool {
30		return atomic.LoadUint32(&t.stopped) == uint32(1)
31	}
32	
33	type backingHeap []*Task
34	
35	func (h backingHeap) Len() int {
36		return len(h)
37	}
38	
39	func (h backingHeap) Less(i, j int) bool {
40		return h[i].Deadline.Before(h[j].Deadline)
41	}
42	
43	func (h backingHeap) Swap(i, j int) {
44		h[i], h[j] = h[j], h[i]
45	}
46	
47	func (h *backingHeap) Push(o any) {
48		t := o.(*Task)
49		*h = append(*h, t)
50	}
51	
52	func (h *backingHeap) Pop() any {
53		old := *h
54		n := len(old)
55		x := old[n-1]
56		*h = old[0 : n-1]
57		return x
58	}
59	
60	type TaskQueue struct {
61		h *backingHeap
62	}
63	
64	func NewTaskQueue() *TaskQueue {
65		return &TaskQueue{h: &backingHeap{}}
66	}
67	
68	func (q *TaskQueue) Enqueue(t *Task) {
69		heap.Push(q.h, t)
70	}
71	
72	func (q *TaskQueue) DeQueue() *Task {
73		if len(*q.h) == 0 {
74			return nil
75		}
76		return heap.Pop(q.h).(*Task)
77	}
78	
79	func (q *TaskQueue) Top() *Task {
80		if len(*q.h) == 0 {
81			return nil
82		}
83		return (*q.h)[0]
84	}
85	
86	func (q *TaskQueue) Size() int {
87		return q.h.Len()
88	}
89	
90	type cmd struct {
91		timeout time.Duration
92		t       *Task
93	}
94	
95	type Scheduler struct {
96		exec        *executor
97		currentTime time.Time
98		queue       *TaskQueue
99		signalChan  chan struct{}
100		cmdChan     chan cmd
101		timeChan    <-chan time.Time
102		stopChan    chan struct{}
103		running     sync.WaitGroup
104	}
105	
106	func NewScheduler(timeChan <-chan time.Time) *Scheduler {
107		s := &Scheduler{
108			queue:      NewTaskQueue(),
109			timeChan:   timeChan,
110			signalChan: make(chan struct{}),
111			cmdChan:    make(chan cmd),
112			stopChan:   make(chan struct{}),
113		}
114	
115		s.exec = &executor{
116			running:  &s.running,
117			queue:    make(chan func(), 1),
118			stopChan: s.stopChan,
119		}
120	
121		return s
122	}
123	
124	func (s *Scheduler) Start() {
125		s.running.Add(2)
126	
127		go s.exec.run()
128		go s.run()
129	}
130	
131	func (s *Scheduler) Stop() {
132		select {
133		case <-s.stopChan:
134			return
135		default:
136		}
137		defer s.running.Wait()
138		close(s.stopChan)
139	}
140	
141	func (s *Scheduler) Schedule(timeout time.Duration, f func()) Stopper {
142		task := &Task{F: f}
143		s.cmdChan <- cmd{
144			t:       task,
145			timeout: timeout,
146		}
147		return task
148	}
149	
150	func (s *Scheduler) run() {
151		defer s.running.Done()
152	
153		s.waitForFirstTick()
154	
155		for {
156			select {
157			case <-s.stopChan:
158				return
159			case now := <-s.timeChan:
160				if s.currentTime.After(now) {
161					continue
162				}
163				s.currentTime = now
164				s.tick()
165			case <-s.signalChan:
166				s.tick()
167			case cmd := <-s.cmdChan:
168				task := cmd.t
169				task.Deadline = s.currentTime.Add(cmd.timeout)
170				s.queue.Enqueue(task)
171			}
172		}
173	}
174	
175	func (s *Scheduler) waitForFirstTick() {
176		select {
177		case s.currentTime = <-s.timeChan:
178		case <-s.stopChan:
179		}
180	}
181	
182	func (s *Scheduler) tick() {
183		for {
184			executedSomeTask := s.checkAndExecute()
185			// If we executed some Task, we can try to execute the next Task if
186			// such a Task is ready to be executed.
187			if !executedSomeTask {
188				return
189			}
190		}
191	}
192	
193	// checkAndExecute checks if there is an executable Task,
194	// and if so then executes it.
195	// Returns true if executed a Task, else false.
196	func (s *Scheduler) checkAndExecute() bool {
197		if s.queue.Size() == 0 {
198			return false
199		}
200	
201		// Should earliest deadline Task be scheduled?
202		if s.queue.Top().Deadline.After(s.currentTime) {
203			return false
204		}
205	
206		task := s.queue.DeQueue()
207	
208		f := func() {
209			if task.isStopped() {
210				return
211			}
212			task.F()
213			select {
214			case s.signalChan <- struct{}{}:
215			case <-s.exec.stopChan:
216				return
217			}
218		}
219	
220		// Check if there is room in the executor queue by trying to enqueue into it.
221		select {
222		case s.exec.queue <- f:
223			// We succeeded in enqueueing, nothing to do.
224			return true
225		default:
226			// We couldn't enqueue to the executor, so re-add the Task.
227			s.queue.Enqueue(task)
228			return false
229		}
230	}
231	
232	type executor struct {
233		running  *sync.WaitGroup
234		stopChan chan struct{}
235		queue    chan func() // 1 capacity channel
236	}
237	
238	func (e *executor) run() {
239		defer e.running.Done()
240		for {
241			select {
242			case <-e.stopChan:
243				return
244			case f := <-e.queue:
245				f()
246			}
247		}
248	}
