194	// InFlightProposal returns an in-flight proposal or nil if there is no such.
195	func (ifp *InFlightData) InFlightProposal() *types.Proposal {
196		ifp.lock.RLock()
197		defer ifp.lock.RUnlock()
198	
199		if ifp.v == nil {
200			return nil
201		}
202	
203		return ifp.v.proposal
204	}
205	
206	// IsInFlightPrepared returns true if the in-flight proposal is prepared.
207	func (ifp *InFlightData) IsInFlightPrepared() bool {
208		ifp.lock.RLock()
209		defer ifp.lock.RUnlock()
210	
211		if ifp.v == nil {
212			return false
213		}
214	
215		return ifp.v.prepared
216	}
217	
218	// StoreProposal stores an in-flight proposal.
219	func (ifp *InFlightData) StoreProposal(prop types.Proposal) {
220		p := prop
221	
222		ifp.lock.Lock()
223		defer ifp.lock.Unlock()
224	
225		ifp.v = &inFlightProposalData{proposal: &p}
226	}
227	
228	// StorePrepares stores alongside the already stored in-flight proposal that it is prepared.
229	func (ifp *InFlightData) StorePrepares(view, seq uint64) {
230		prop := ifp.InFlightProposal()
231		if prop == nil {
232			panic("stored prepares but proposal is not initialized")
233		}
234		p := prop
235	
236		ifp.lock.Lock()
237		defer ifp.lock.Unlock()
