386	func signedViewDataToString(svd *protos.SignedViewData) string {
387		if svd == nil {
388			return "empty ViewData"
389		}
390		vd := &protos.ViewData{}
391		if err := proto.Unmarshal(svd.RawViewData, vd); err != nil {
392			return fmt.Sprintf("<malformed viewdata from %d>", svd.Signer)
393		}
394	
395		return fmt.Sprintf("<ViewData signed by %d with NextView: %d>",
396			svd.Signer, vd.NextView)
